package org.apache.commons.compress.compressors.lzma;

import org.junit.Test;
import static org.junit.Assert.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class LZMAUtils_ESTest_test04 extends LZMAUtils_ESTest_scaffolding {

    /**
     * The LZMA classes are present on the test classpath, so the availability
     * check should report that LZMA compression is supported.
     */
    @Test(timeout = 4000)
    public void isLZMACompressionAvailableReturnsTrueWhenClassesPresent() throws Throwable {
        boolean lzmaAvailable = LZMAUtils.isLZMACompressionAvailable();

        assertTrue(lzmaAvailable);
    }
}
